int n = 3, a[3][3] = {{1,0,0},{0,1,0},{0,0,1}};
int dr[4] = {1,0,-1,0}, dc[4] = {0,1,0,-1};
int size[9], cnt;

bool compare(int x, int y) {
    return x>y;
}

int dfs(int r, int c) {
    a[r][c] = 2;
    int sum = 1;
    for(int i=0; i<4; i++) {
        int nr = r+dr[i], nc = c+dc[i];
        if(nr>=0 && nr<n && nc>=0 && nc<n && a[nr][nc]==1)
            sum += dfs(nr,nc);
    }
    return sum;
}

int main() {
    for(int r=0; r<n; r++)
        for(int c=0; c<n; c++)
            if(a[r][c]==1) size[cnt++] = dfs(r,c);
    sort(size, size+cnt, compare);
    printf("%d ", cnt);
    for(int i=0; i<cnt; i++) printf("%d ", size[i]);
    return 0;
}

