#include <stdio.h>

int a[2][2] = {{0,1},{1,0}}, white, green;

void f(int r, int c, int n) {
    int same = 1;
    for(int i=r; i<r+n; i++)
        for(int j=c; j<c+n; j++)
            if(a[i][j]!=a[r][c]) same = 0;
    if(same) {
        if(a[r][c]) green++;
        else white++;
        return;
    }
    int half = n/2;
    f(r,c,half);
    f(r+half,c,half);
    f(r,c+half,half);
    f(r+half,c+half,half);
}

int main() {
    f(0,0,2);
    printf("%d %d", white, green);
    return 0;
}

